 return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],null,null,(int)$task['lock_version'],(int)$step['lock_version']);});}
 public function beginApprovedChatExecution(string$public,int$u,string$trace,string$model):ChatTaskContext{return$this->resumeApprovedToolTask($public,$u,$trace,$model)['context'];}
 /** @return array{outcome:'resume_started'|'resume_recovered'|'already_resumed',context:ChatTaskContext,lease_token:?string} */
 public function resumeApprovedToolTask(string$public,int$u,string$trace,string$model):array{return$this->tx(function()use($public,$u,$trace,$model){
  $found=$this->tasks->findOwnedByPublicId($public,$u)??throw new TaskNotFoundException('not_found');$task=$this->tasks->lockOwnedForResponse((int)$found['id_'],$u)??throw new TaskNotFoundException('not_found');
  $stepId=(int)($task['current_step_id_']??0);if($stepId<1)throw new TaskTransitionException('tool_resume_not_resumable');$step=$this->steps->lockForRetry($stepId,(int)$task['id_'])??throw new TaskTransitionException('tool_resume_not_resumable');TaskScheduleEligibility::assertEligible($task);
  $input=json_decode((string)($step['input_json']??''),true);if(!is_array($input)||($input['execution_mode']??'sync')!=='sync')throw new TaskTransitionException('tool_resume_sync_required');
  $approval=TaskToolApprovalState::fromCheckpoint($step['checkpoint_json']===null?null:(string)$step['checkpoint_json']);if($approval->status!==TaskToolApprovalState::APPROVED||$approval->identity===null)throw new TaskTransitionException('tool_resume_not_resumable');
  $history=$this->executions->historyByStep($stepId);$origin=null;foreach($history as$row)if((int)$row['id_']===$approval->identity->proposalExecutionId)$origin=$row;
  if($origin===null||(int)$origin['task_id_']!==(int)$task['id_']||(int)$origin['step_id_']!==$stepId||(string)$origin['status']!=='completed')throw new TaskTransitionException('tool_resume_origin_invalid');
  $existing=$this->executions->continuationAfter($history,$approval->identity->proposalExecutionId);$owner='http-sync';$leaseToken=TaskPublicId::generate();$leaseSeconds=300;
  if($existing!==null){if($task['status']!=='running'||$step['status']!=='running'||(string)$existing['status']!=='running')throw new TaskTransitionException('tool_resume_not_resumable');if(!$this->executions->claimHttpContinuation((int)$existing['id_'],$owner,$leaseToken,$leaseSeconds))return['outcome'=>'already_resumed','context'=>new ChatTaskContext((int)$task['id_'],$public,$stepId,(int)$existing['id_'],null,(int)$task['lock_version'],(int)$step['lock_version']),'lease_token'=>null];return['outcome'=>'resume_recovered','context'=>new ChatTaskContext((int)$task['id_'],$public,$stepId,(int)$existing['id_'],(string)$existing['trace_id'],(int)$task['lock_version'],(int)$step['lock_version']),'lease_token'=>$leaseToken];}
  if($task['status']!=='ready'||$step['status']!=='ready')throw new TaskTransitionException('tool_resume_not_resumable');
  $attempt=(new TaskClaimAttemptBudget())->nextAttemptNumber((int)$task['id_'],$stepId,(int)$task['max_attempts'],$history,(string)$step['checkpoint_json']);$execution=$this->executions->create((int)$task['id_'],$stepId,$trace,$model,$attempt);$this->event((int)$task['id_'],'execution_created',null,'queued','Continuación HTTP aprobada creada.',$u,$stepId,(int)$execution['id_']);
  $task=$this->tasks->updateStatus((int)$task['id_'],$u,'running',(int)$task['lock_version']);$step=$this->steps->updateStatus($stepId,'running',(int)$step['lock_version']);$this->executionMachine->assertTransition('queued','running');$execution=$this->executions->updateStatus((int)$execution['id_'],'running',null,$model);if(!$this->executions->claimHttpContinuation((int)$execution['id_'],$owner,$leaseToken,$leaseSeconds))throw new TaskConcurrencyException('tool_resume_lease_conflict');$this->event((int)$task['id_'],'execution_started','queued','running','Continuación HTTP iniciada.',$u,$stepId,(int)$execution['id_']);
  return['outcome'=>'resume_started','context'=>new ChatTaskContext((int)$task['id_'],$public,$stepId,(int)$execution['id_'],$trace,(int)$task['lock_version'],(int)$step['lock_version']),'lease_token'=>$leaseToken];
 });}
 public function beginChatExecution(ChatTaskContext$c,int$u,string$trace,string$model):ChatTaskContext{return$this->tx(function()use($c,$u,$trace,$model){$task=$this->tasks->lockOwnedForResponse($c->taskId,$u)??throw new TaskNotFoundException('not_found');$step=$this->steps->lockForRetry($c->stepId,(int)$task['id_'])??throw new TaskNotFoundException('step_not_found');TaskScheduleEligibility::assertEligible($task);if($task['status']!=='ready'||$step['status']!=='ready')throw new TaskTransitionException('task_not_ready');$history=$this->executions->historyByStep((int)$step['id_']);$attempt=(new TaskClaimAttemptBudget())->nextAttemptNumber((int)$task['id_'],(int)$step['id_'],(int)$task['max_attempts'],$history,$step['checkpoint_json']===null?null:(string)$step['checkpoint_json']);$execution=$this->executions->create((int)$task['id_'],(int)$step['id_'],$trace,$model,$attempt);$this->event((int)$task['id_'],'execution_created',null,'queued','Ejecución creada.',$u,(int)$step['id_'],(int)$execution['id_']);$task=$this->tasks->updateStatus((int)$task['id_'],$u,'running',(int)$task['lock_version']);$step=$this->steps->updateStatus((int)$step['id_'],'running',(int)$step['lock_version']);$this->executionMachine->assertTransition('queued','running');$execution=$this->executions->updateStatus((int)$execution['id_'],'running',null,$model);$this->event((int)$task['id_'],'execution_started','queued','running','Ejecución iniciada.',$u,(int)$step['id_'],(int)$execution['id_']);return new ChatTaskContext((int)$task['id_'],(string)$task['public_id'],(int)$step['id_'],(int)$execution['id_'],$trace,(int)$task['lock_version'],(int)$step['lock_version']);});}
 public function approveChatTask(int$id,int$u,int$lock):array{return$this->decideChatTask($id,$u,$lock,true);}
