 private function decideChatTask(int$id,int$u,int$lock,bool$approve):array{return$this->tx(function()use($id,$u,$lock,$approve){$task=$this->tasks->findOwnedById($id,$u)??throw new TaskNotFoundException('not_found');if((int)$task['lock_version']!==$lock)throw new TaskConcurrencyException('concurrency_conflict');if($task['status']!=='waiting_user')throw new TaskTransitionException('task_not_waiting_user');$stepId=(int)($task['current_step_id_']??0);if($stepId<1)throw new TaskNotFoundException('step_not_found');$step=$this->steps->findById($stepId)??throw new TaskNotFoundException('step_not_found');if((int)$step['task_id_']!==$id||$step['status']!=='waiting_user')throw new TaskTransitionException('current_step_not_waiting_user');$to=$approve?'ready':'cancelled';$this->machine->assertTransition('waiting_user',$to);$this->stepMachine->assertTransition('waiting_user',$to);$task=$this->tasks->updateStatus($id,$u,$to,$lock);$step=$this->steps->updateStatus((int)$step['id_'],$to,(int)$step['lock_version']);$this->events->append(['task_id'=>$id,'step_id'=>(int)$step['id_'],'actor_type'=>'user','actor_user_id'=>$u,'event_key'=>$approve?'task_approved':'task_rejected','from_status'=>'waiting_user','to_status'=>$to,'summary'=>$approve?'Tarea aprobada por el usuario.':'Tarea rechazada por el usuario.']);return$task;});}
 public function completeChatTurn(ChatTaskContext$c,int$u,int$message,string$summary,string$model):void{$this->tx(function()use($c,$u,$message,$summary,$model){$execution=$this->executions->findById($c->executionId)??throw new RuntimeException('execution_not_found');if($execution['status']==='running'){$this->executionMachine->assertTransition('running','completed');$this->executions->updateStatus($c->executionId,'completed',null,$model);$this->event($c->taskId,'execution_completed','running','completed','Ejecución completada.',$u,$c->stepId,$c->executionId);}$step=$this->steps->findById($c->stepId)??throw new RuntimeException('step_not_found');if($step['status']==='running'){$this->stepMachine->assertTransition('running','completed');$this->steps->updateStatus($c->stepId,'completed',(int)$step['lock_version']);$this->event($c->taskId,'step_completed','running','completed','Step completado.',$u,$c->stepId);}$task=$this->tasks->findOwnedById($c->taskId,$u)??throw new RuntimeException('task_not_found');if($task['status']==='running'){$this->machine->assertTransition('running','completed');$this->tasks->assignResult($c->taskId,$u,$message,$summary);$this->tasks->updateStatus($c->taskId,$u,'completed',(int)$task['lock_version'],['result_summary'=>$summary]);$this->event($c->taskId,'task_completed','running','completed','Tarea completada.',$u);}});}
 public function failChatTurn(ChatTaskContext$c,int$u,string$error):void{$this->tx(function()use($c,$u,$error){$e=$this->executions->findById($c->executionId);if($e&&$e['status']==='running'){$this->executionMachine->assertTransition('running','failed');$this->executions->updateStatus($c->executionId,'failed',$error);$this->event($c->taskId,'execution_failed','running','failed','Ejecución fallida.',$u,$c->stepId,$c->executionId);}$s=$this->steps->findById($c->stepId);if($s&&$s['status']==='running'){$this->stepMachine->assertTransition('running','failed');$this->steps->updateStatus($c->stepId,'failed',(int)$s['lock_version'],['error_message'=>$error]);$this->event($c->taskId,'step_failed','running','failed','Step fallido.',$u,$c->stepId);}$t=$this->tasks->findOwnedById($c->taskId,$u);if($t&&$t['status']==='running'){$this->machine->assertTransition('running','failed');$this->tasks->updateStatus($c->taskId,$u,'failed',(int)$t['lock_version'],['error_code'=>'chat_pipeline_failed','error_message'=>$error]);$this->event($c->taskId,'task_failed','running','failed','Tarea fallida.',$u);}});}
 private function event(int$task,string$key,?string$from,string$to,string$summary,int$u,?int$step=null,?int$execution=null):void{$this->events->append(['task_id'=>$task,'step_id'=>$step,'execution_id'=>$execution,'actor_type'=>'system','actor_user_id'=>$u,'event_key'=>$key,'from_status'=>$from,'to_status'=>$to,'summary'=>$summary]);}
